import requests

BASE_URL = "http://localhost:8000"
ADMIN_JWT = "eyJhbGciOiJFUzI1NiIsImtpZCI6ImI4MTI2OWYxLTIxZDgtNGYyZS1iNzE5LWMyMjQwYTg0MGQ5MCIsInR5cCI6IkpXVCJ9..7tnorXc_v1GajgbKOx_eL1YOszeBUfjHR8eD_sTpsMVGd1byScCiaea2NrexKmTDL3dIlmobE5Mqry_s39Blkw"
TIMEOUT = 30

def test_list_past_verification_decisions():
    url = f"{BASE_URL}/api/admin/verification/history"
    headers_with_auth = {
        "Authorization": f"Bearer {ADMIN_JWT}"
    }
    # Success case: with valid admin JWT
    try:
        response = requests.get(url, headers=headers_with_auth, timeout=TIMEOUT)
        assert response.status_code == 200, f"Expected 200 OK, got {response.status_code}"
        data = response.json()
        assert isinstance(data, list), "Response data should be a list"
    except requests.RequestException as e:
        assert False, f"Request failed: {e}"

    # Failure case: without admin authorization
    try:
        response = requests.get(url, timeout=TIMEOUT)
        assert response.status_code == 403, f"Expected 403 Forbidden without auth, got {response.status_code}"
    except requests.RequestException as e:
        assert False, f"Request failed: {e}"

test_list_past_verification_decisions()